"""US purchasing units and transparent dated estimate from the native takeoff."""
from pathlib import Path
import json,csv,math,html
ROOT=Path(__file__).resolve().parents[1]
rates=json.loads((ROOT/'materials/us-rate-scenario-2026-11-02.json').read_text());src=rates['sources']
take=json.loads((ROOT/'materials/quantities.json').read_text());items={r['item']:r for r in take['items']}
rows=[]
def net(part):return float(items[part]['net_quantity'])
def add(name,category,qty,unit,low,high,source='',evidence='Planning allowance',basis='',netq=None,waste=None):
    assert qty>=0 and 0<=low<=high
    rows.append(dict(item=name,category=category,net_quantity=netq,quantity=round(qty,4),purchase_unit=unit,allowance_percent=waste,unit_low_usd=low,unit_high_usd=high,low_usd=round(qty*low,2),high_usd=round(qty*high,2),evidence=evidence,source_title=src[source]['title'] if source else '',source_url=src[source]['url'] if source else '',basis=basis))
def observed(key):return src[key]['observed_price']
def boards(part,stock,stocklen,waste,key,low=None,high=None):
    q=net(part);count=math.ceil(q*(1+waste/100)/stocklen)
    add(stock,'Framing',count,'board-equivalent',low or observed(key),(high or (low or observed(key))*1.3),key,'Advertised benchmark + authored upper reserve',f'{q:.2f} net lf x {1+waste/100:.2f} / {stocklen} ft, rounded up. Volume-derived planning equivalent; not a member count, splice plan or cut list.',q,waste)
boards('Partition timber','Nominal 2x4 x 10 ft SPF #2 or engineer-approved grade; dressed 1.5 x 3.5 in',10,15,'2x4')
boards('Partition header 2x6','Nominal 2x6 x 8 ft header stock; dressed 1.5 x 5.5 in',8,15,'2x6')
q=net('Header plywood spacer');add('1/2 in x 4 ft x 8 ft plywood for header spacers','Framing',math.ceil(q*1.15/32),'sheet',30,50,'plywood',basis='1/2 in spacer; roof-sheathing listing is sourcing-family reference, not an observed 1/2 in price',netq=q,waste=15)
for p in ['Concrete footings','Concrete slab','Retaining concrete core']:
    q=net(p);add(p+' — ready mix, specified mix TBD','Concrete',math.ceil(q*1.05*4)/4,'cy',180,280,'concrete',basis='Measured native volume plus 5%, rounded to 1/4 cy. Excludes delivery, pump, placement, forms and steel.',netq=q,waste=5)
add('Reinforcing steel supply, ties, chairs and anchor dowels','Concrete',1,'lot',4000,9000,basis='Authored supply allowance only; bar sizes, pounds, spacing, laps and cover require an engineered schedule. No measured steel quantity exists.')
q=net('Subslab aggregate');add('Specified capillary-break aggregate','Concrete',math.ceil(q*1.1),'cy',50,90,'aggregate',basis='10% loose-volume allowance; compaction and gradation unverified; trucking separate',netq=q,waste=10)
for p,key,thickness in [('Subslab insulation','xps2','2 in'),('Wall rigid insulation','xps3','3 in')]:
    q=net(p);add(f'{thickness} XPS rigid insulation, 4 ft x 8 ft','Insulation',math.ceil(q*1.1/32),'board',observed(key),round(observed(key)*1.25,2),key,'Advertised benchmark + authored upper reserve','25 psi product benchmark; required bearing, termite/envelope approval and R-value remain design inputs',q,10)
q=net('Roof continuous insulation');add('Roof-approved new polyiso, 3 in x 4 ft x 8 ft, TWO layers (6 in total)','Insulation',2*math.ceil(q*1.1/32),'board',55,90,'roofiso',basis='Two layers counted separately; 10% cutting waste per layer. Final thermal/uplift/fire/fastener design TBD.',netq=2*q,waste=10)
q=net('Wall waterproofing');add('Self-adhered foundation waterproofing, nominal 200 sf roll','Waterproofing',math.ceil(q*1.15/200),'roll',observed('wallwater'),round(observed('wallwater')*1.3,2),'wallwater','Advertised benchmark + authored upper reserve','15% for seams/cutting; all exterior faces retained from current study; primer/detail products separate',q,15)
q=net('Wall drainage layer');add('Drainage/protection composite, 4 ft x 50 ft roll','Waterproofing',math.ceil(q*1.1/200),'roll',observed('drainmat'),round(observed('drainmat')*1.3,2),'drainmat','Advertised benchmark + authored upper reserve','10% seam/cutting reserve; attachment and termination details TBD',q,10)
q=net('Slab vapor barrier');add('15 mil underslab vapor barrier, 14 ft x 140 ft roll','Waterproofing',math.ceil(q*1.15/1960),'roll',observed('vapor'),round(observed('vapor')*1.2,2),'vapor','Advertised benchmark + authored upper reserve','15% laps/penetrations; two full rolls leave substantial surplus; smaller roll quote may reduce cost',q,15)
add('Compatible waterproofing primers, boots, tape, mastic and terminations','Waterproofing',1,'lot',1800,3500,'wallwater',basis='Additional materials allowance; no labor; compatible manufacturer-approved assembly required')
q=net('Footing drain reservation');add('Engineered 4 in nominal footing-drain pipe, 10 ft sticks','Drainage',math.ceil(q*1.1/10),'stick',25,55,'pipe',basis='10% plus round-up. Link is an observed $16.38 thin-wall price comparison only; budget uses higher authored rate pending approved pipe class/burial design. Not a recommendation to use D2729 at 6 ft burial.',netq=q,waste=10)
add('Drain stone, filter fabric, cleanouts, outlet and upslope interceptor materials','Drainage',1,'lot',2500,6000,'aggregate',basis='Provisional materials only. Outlet length and trench/soil design are not measured.')
q=net('Engineered roof member reservation');add('Engineered 16 in-depth roof joist system — supplier-designed','Framing',math.ceil(q*1.1),'lf',6,12,'joist',basis='Complete joist assembly priced once; 10% bearing/trim reserve. Native boxes are reservations, not joist sections or an approved series.',netq=q,waste=10)
add('Transfer beam, posts, rim/blocking, hangers and anchors package','Framing',1,'lot',4500,10000,'joist',basis='Engineered quote required; includes connectors; partition headers already counted separately')
q=net('Roof deck');add('23/32 in rated roof sheathing plywood, 4 ft x 8 ft','Roof',math.ceil(q*1.1/32),'sheet',observed('plywood'),60,'plywood','Supplier search-listing benchmark; full page blocked; verify price','10% waste; final span rating, edge support, fastening and panel layout TBD',q,10)
q=net('Roof membrane');add('60 mil roof membrane benchmark, 10 ft x 100 ft roll','Roof',4,'roll',observed('epdm'),1400,'epdm','Advertised benchmark + authored upper reserve','Four roughly 66 ft courses, allowing laps across the roughly 38 ft roof depth; four full rolls purchased. Area-only ceil(area/1000)=3 is NOT used. Offcuts retained; final roll/seam plan by roofer.',q,None)
add('Roof cover board, adhesives, flashing, fascia, gutters and downspouts','Roof',1,'lot',6500,12000,'roofiso',basis='Covers the native Roof protective finish reservation plus unmodeled roof accessories; do not add that native row again')
q=net('Partition gypsum');add('1/2 in drywall, 4 ft x 8 ft wall sheets','Finishes',math.ceil(q*1.1/32),'sheet',observed('drywall'),25,'drywall','Advertised benchmark + authored upper reserve','10% waste; moisture-rated/wet-area backers included by separate allowance',q,10)
q=net('Ceiling gypsum');add('5/8 in sag-resistant ceiling board, 4 ft x 8 ft','Finishes',math.ceil(q*1.1/32),'sheet',22,32,'drywall',basis='Authored 5/8 in ceiling-board rate; linked 1/2 in product is a supplier reference only. Native ceiling is a thickness reservation; do not infer fire rating.',netq=q,waste=10)
q=net('Exterior wall inside finish');add('Mineral plaster over concrete interior faces','Finishes',math.ceil(q*1.1),'sf',1.25,2.5,basis='Material-only authored allowance; final finish/bonding system and supplier quote TBD',netq=q,waste=10)
add('Drywall tape/compound, screws, corner bead, wet-area backers and paint','Finishes',1,'lot',3000,6000,basis='Materials only; installation labor in overall budget')
add('8 interior nominal 36 x 84 in door units and hardware','Openings',8,'each',240,500,basis='Source aperture reservation is 36 in, not a finished prehung rough opening. Increase rough openings during detailed framing coordination; not a ready-to-order size.')
add('2 exterior nominal 36 x 84 in insulated entry units','Openings',2,'each',750,1800,basis='Rough-opening/product and landing coordination required; materials only')
add('3 bedroom escape-window units, approximately 4 x 5 ft openings','Openings',3,'each',800,1700,basis='Supplier must certify operable net escape area and sill, not just frame dimensions. Exact product unselected.')
add('1 living window unit, approximately 6 x 6 ft opening','Openings',1,'each',1000,2200,basis='Product, structural header, safety glazing and daylight design TBD')
add('Electrical materials, service panel, alarms and lighting','Services',1,'lot',6500,11500,basis='Authored house materials allowance; utility line extension outside house is separate')
add('Plumbing materials, two baths, kitchen and laundry fixtures','Services',1,'lot',8500,15000,basis='House materials only; septic/water source are separate installed allowances')
add('Heat pump, balanced ventilation, ducts and water heater equipment','Services',1,'lot',9000,16000,basis='Equipment/material allowance; load calculation and installer quote required')
add('Cabinets, counters, appliances and finish flooring materials','Finishes',1,'lot',18000,32000,basis='Provisional midrange selection allowance; source furniture placeholders are not counted')
add('South patio materials, approximately 680 sf','Site materials',680,'sf',4,8,basis='Patio is outside enclosed area; material package only; labor included in house/site labor allowance as coordinated')
materials_low=round(sum(r['low_usd'] for r in rows),2);materials_high=round(sum(r['high_usd'] for r in rows),2)
overall=[dict(item='House and patio materials',low_usd=materials_low,high_usd=materials_high,basis='All material rows above; no labor')]
def overall_add(name,lo,hi,basis):overall.append(dict(item=name,low_usd=round(lo,2),high_usd=round(hi,2),basis=basis))
overall_add('House construction labor, concrete forming/placement, MEP installation, rentals and pumping',105000,185000,'Authored combined labor/equipment allowance; excludes site earthworks and separately listed utilities. No supplier or contractor quote.')
overall_add('Surveyed site excavation, berm/backfill and grading labor/equipment',20000,55000,'Authored installed sitework allowance; excludes drain materials already included. Unknown rock/groundwater may exceed range.')
overall_add('Septic system installed',12000,25000,'Authored allowance pending soils/permit design; not a quoted system')
overall_add('Water source / well or service connection installed',10000,35000,'Authored allowance; no well depth, yield or service location known')
overall_add('Electric utility extension / connection',5000,25000,'Authored allowance, utility quote required; off-grid PV/storage excluded')
overall_add('Material freight and remote delivery reserve',materials_low*.08,materials_high*.12,'Authored 8%-12% material-cost reserve; includes ready-mix transport; long-haul concrete feasibility remains open')
overall_add('Sales/use-tax reserve',materials_low*.08,materials_high*.10,'Authored 8%-10% reserve on material subtotal, NOT a verified tax rate or tax determination')
construction_low=sum(r['low_usd'] for r in overall);construction_high=sum(r['high_usd'] for r in overall)
overall_add('General contractor overhead / profit reserve',construction_low*.15,construction_high*.15,'Authored 15% of preceding construction subtotal; remove/rework for owner-builder procurement, without assuming labor is free')
overall_add('Design, geotechnical, survey and permit fees',18000,35000,'Authored professional/permit allowance; refine possible overlap in survey/site quote')
prelo=sum(r['low_usd'] for r in overall);prehi=sum(r['high_usd'] for r in overall)
overall_add('Concept design / scope contingency',prelo*.2,prehi*.2,'20% of all preceding rows, including OH/profit and fees; not a guarantee of maximum cost')
totlo=round(sum(r['low_usd'] for r in overall),2);tothi=round(sum(r['high_usd'] for r in overall),2)
estimate=dict(date=rates['date'],currency='USD',source_sha256=take['source_sha256'],native_sha256=take['native_sha256'],material_low_usd=materials_low,material_high_usd=materials_high,overall_low_usd=totlo,overall_high_usd=tothi,gross_sf=2175.94,material_rows=rows,overall_rows=overall,excluded=['Land purchase and finance','Soil-covered roof or greenhouse','Off-grid PV/battery/cistern package (optional additional authored $25,000-$65,000)','Rock blasting, major dewatering or soil stabilization beyond stated reserves','Driveway/road beyond immediate grading, landscaping, garage/outbuildings','Insurance, escalation after research date and owner carrying costs'])
(ROOT/'materials/estimate.json').write_text(json.dumps(estimate,indent=2))
with (ROOT/'materials/us-purchasing-and-costs.csv').open('w',newline='',encoding='utf-8-sig') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
with (ROOT/'materials/overall-budget.csv').open('w',newline='',encoding='utf-8-sig') as f:
    w=csv.DictWriter(f,fieldnames=list(overall[0]));w.writeheader();w.writerows(overall)
money=lambda x:f'${x:,.0f}'
body=['# US material sourcing and draft cost breakdown','',f'Checked {rates["date"]} · USD · selected A, 64 ft x 34 ft · 2,175.94 sf gross / 1,914.18 sf clear floor','',f'**Materials planning range: {money(materials_low)}–{money(materials_high)}. Overall project scenario: {money(totlo)}–{money(tothi)}**, including the explicitly authored labor, site/service, delivery, tax, overhead, professional-fee and 20% contingency allowances below. Land and optional off-grid package are excluded. These are concept estimates, not bids or an order-ready list.','', '## Imperial stock and geometry','', 'All buying units are US customary: boards in feet and inches, 4 ft x 8 ft sheets/boards, rolls, linear feet (lf), square feet (sf), cubic feet (cf), cubic yards (cy), pounds (lb), and each. Blender displays Imperial units. Exact dressed 2x4 = 1.5 x 3.5 in; dressed 2x6 = 1.5 x 5.5 in. Stud spacing = 16 in on center. Header assembly = two 2x6 plies + 1/2 in plywood spacer. Header grade/size and roof framing remain engineering reservations. Plans retain integer-mm computation solely to preserve reviewed source topology; that is not the stock specification.','', 'The original rounded framing was rebuilt and remeasured with exact inch-based sections. Header lumber and spacer plywood are no longer hidden in the 2x4 volume equivalent. A 10 ft 2x4 budget count includes cutting/waste, but a cut/splice schedule is still required; long plates may need 12/16 ft stock. Buy 10 ft studs for the current 9 ft datum and cut to the detailed plate/ceiling design; do not assume a standard precut length fits.','', 'Roof deck uses a 23/32 in rated sheet allowance; ceiling purchasing assumes 5/8 in sag-resistant board. Source roof/ceiling/membrane layer thicknesses remain schematic and must be coordinated to the selected tested assembly. The thermal design is not code certified.','', '## Purchasing and material costs','', 'Net native quantities, waste factors and purchase rounding are in [the purchasing CSV](us-purchasing-and-costs.csv); [raw model takeoff](bill-of-materials.csv) retains measurements. Unit prices below are lower/upper scenario inputs, not claims that all prices were observed.','', '| Material / purchasing description | Quantity | Unit | Unit USD low–high | Extended USD low–high | Evidence / source |','|---|---:|---|---:|---:|---|']
for r in rows:
    link=f'[{r["source_title"]}]({r["source_url"]})' if r['source_url'] else 'Authored allowance; quote needed'
    body.append(f'| {r["item"]} | {r["quantity"]:g} | {r["purchase_unit"]} | {money(r["unit_low_usd"])}–{money(r["unit_high_usd"])} | {money(r["low_usd"])}–{money(r["high_usd"])} | {r["evidence"]}; {link} |')
body+=['',f'**Material subtotal: {money(materials_low)}–{money(materials_high)}.**','','## Overall project scenario','','| Scope | Low USD | High USD | Basis |','|---|---:|---:|---|']
for r in overall:body.append(f'| {r["item"]} | {money(r["low_usd"])} | {money(r["high_usd"])} | {r["basis"]} |')
body +=[f'| **TOTAL** | **{money(totlo)}** | **{money(tothi)}** | Scenario endpoints, not statistical confidence bounds |','',f'Approximately {money(totlo/2175.94)}–{money(tothi/2175.94)} per gross enclosed sf including listed site/services and reserves; do not compare this directly to a materials-only or house-only contractor rate.','', '## Purchasing qualifications','']
for r in rows:body.append(f'- **{r["item"]}:** {r["basis"]}')
body+=['','## Supplier evidence and retrieval limits','', 'Prices were read from public supplier pages/catalog/search listings on the checked date. Local store, quantity discounts, availability and Portal freight have not been confirmed. No supplier has been contacted or quote requested. Advertised prices are benchmarks; selected brands are not an approved assembly. Upper rates and every item labeled Planning allowance were authored for this study.']
for key,s in src.items():
    p='No public price adopted' if s['observed_price'] is None else f'Observed {money(s["observed_price"])} / {s["unit"]}'
    body.append(f'- [{s["title"]}]({s["url"]}): {p}. {s["evidence"]}')
body+=['','The low-price corrugated drain listing considered during research has a published burial limit below the assumed rear-wall burial and is not specified. Thin-wall PVC benchmark is likewise not burial-depth approval. Engineer the pipe class, outlet, bedding, soil filter and surcharge loads. Waterproofing membrane must bond to the approved substrate, continue at footings/penetrations and connect to compatible protection/drainage. The model is an assembly reservation, not that detail.','', 'No reinforcement schedule exists. Concrete pricing is for concrete material only; the house labor/forming/placement allowance reserves cost for the work, and the framing/structural package still needs a rebar/formwork quote. A separate **$4,000–$9,000 steel supply allowance** is included below by the estimate generator if enabled; see estimate rows for the authoritative arithmetic.','', '## Exclusions','']+[f'- {x}' for x in estimate['excluded']]
# Reinforcement must be an actual priced row, not just narrative. Guard that here.
body=[line for line in body if 'if enabled' not in line]
body+=['', 'Reinforcing steel quantity is TBD. Its supply cost is included in the structural/rebar allowance row; it is not an engineered bar schedule. Concrete forms/rental/placement labor are in the house construction labor/equipment row.','',f'Source SVG SHA256: `{take["source_sha256"]}`',f'Native Blender SHA256: `{take["native_sha256"]}`','']
(ROOT/'materials/cost-breakdown.md').write_text('\n'.join(body),encoding='utf-8')
# HTML report is generated directly from the same structured rows, without a Markdown dependency.
escape=html.escape
def table(headers,rr):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rr)+'</tbody></table></div>'
overallhtml=table(['Scope','Low USD','High USD','Basis'],[[escape(r['item']),money(r['low_usd']),money(r['high_usd']),escape(r['basis'])] for r in overall])
materialhtml=table(['Material / stock','Buy quantity','Unit price low–high','Extended low–high','Basis / supplier'],[[escape(r['item']),f'{r["quantity"]:g} {escape(r["purchase_unit"])}',money(r['unit_low_usd'])+'–'+money(r['unit_high_usd']),money(r['low_usd'])+'–'+money(r['high_usd']),escape(r['evidence'])+'<br>'+escape(r['basis'])+(f'<br><a href="{escape(r["source_url"])}" rel="noopener">{escape(r["source_title"])}</a>' if r['source_url'] else '')] for r in rows])
sourceshtml=''.join(f'<li><a href="{escape(s["url"])}">{escape(s["title"])}</a> — {escape(s["evidence"])}</li>' for s in src.values())
document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>US materials & costs · Portal Earthship</title><link rel="stylesheet" href="../assets/site.css"></head><body><main><nav><a href="../index.html">← Design overview</a><a href="us-purchasing-and-costs.csv">Purchasing CSV</a><a href="cost-breakdown.md">Markdown document</a><a href="overall-budget.csv">Overall budget CSV</a></nav><header><p class="eyebrow">US SOURCING · CHECKED {rates['date']}</p><h1>Materials & draft costs</h1><p class="lede">Exact dressed lumber. US stock sizes. Visible assumptions.</p></header><div class="metrics"><article><span>Materials only</span><strong>{money(materials_low)}–{money(materials_high)}</strong></article><article><span>Overall scenario, including reserves</span><strong>{money(totlo)}–{money(tothi)}</strong></article></div><p class="notice">Concept estimates, not bids. Overall range includes authored allowances for labor, site utilities, delivery, tax, overhead, design fees and 20% contingency. Land and optional off-grid package excluded.</p><section><h2>US purchasing basis</h2><p>Nominal 2×4 = actual 1½″ × 3½″; nominal 2×6 = actual 1½″ × 5½″. Stud spacing 16″ on center. Header study uses two 2×6 plies with a ½″ plywood spacer. Lumber board counts are volume-derived budgeting equivalents; grade, spans, member cuts and plate splices need final design.</p><p>Sheets and boards: 4′ × 8′. Concrete and aggregate: cubic yards. Membranes: mils and full rolls. Pipe: nominal inches and 10′ sticks. Quantities are rounded for buying, with explicit waste. Engineering source geometry retains its reviewed integer-mm datums; no metric stock sizes are specified.</p></section><section><h2>Overall project scenario</h2>{overallhtml}<p><b>Total {money(totlo)}–{money(tothi)}</b> · approximately {money(totlo/2175.94)}–{money(tothi/2175.94)} per gross enclosed sf, including the listed site/services and reserves.</p></section><section><h2>Material purchase breakdown</h2><p>Only rows with advertised benchmarks use observed prices. All other prices are authored planning allowances. Upper rates reserve uncertainty; no Portal supplier quote or availability is claimed.</p>{materialhtml}</section><section><h2>What still needs a quote</h2><p>Ready-mix transport to Portal, rebar/formwork, engineered joists and transfer supports, waterproofing assembly, deep-burial pipe class, excavation, utilities and installation. The thin-wall drain link is a price comparison only and is not approved for the proposed burial depth. A 36″ door source aperture is not a finalized prehung rough opening.</p><p>Four 10′ × 100′ membrane rolls are reserved for four approximately 66′ roof courses. Three rolls based only on total square footage would not establish a viable seam layout. New roof-approved insulation is priced as two 3″ layers; reclaimed boards are not used.</p><details><summary>Supplier sources and evidence</summary><ul>{sourceshtml}</ul></details><h3>Exclusions</h3><ul>{''.join('<li>'+escape(x)+'</li>' for x in estimate['excluded'])}</ul></section><footer>Draft A · Not for construction · <a href="../README.md">Project notes</a> · All amounts USD</footer></main></body></html>'''
(ROOT/'materials/costs.html').write_text(document,encoding='utf-8')
print(json.dumps({k:estimate[k] for k in ['material_low_usd','material_high_usd','overall_low_usd','overall_high_usd']},indent=2))
